function FDJ.KoreanMapFloor(floor)
    if (FDJ.GetLanguage and FDJ.GetLanguage() or GetLocale()) ~= "koKR" then return floor end
    local originalPath = floor.tiles or floor.texture
    local localizedPath = type(originalPath) == "string" and CLASSIC[originalPath:lower()]
    if not localizedPath then return floor end
    local copy = {}
    for key, value in pairs(floor) do copy[key] = value end
    -- 원본 한국어 타일을 우선하며, API의 영문 FileDataID로 다시 선택되지 않게 한다.
    copy.tiles, copy.texture, copy.uiMapID = localizedPath, nil, nil
    return copy
end
